-- Limit the public anon key to what the browser uses: Realtime UPDATEs on public.games.
--
-- Why (review, 2026-10-21): the anon key ships in the JS bundle, and 0005–0008 granted it SELECT
-- on every table. Anyone could page through fatigue_scores or shot_value_surface over the Data
-- API, past the CDN and the Vercel firewall, and every row read is Supabase egress. The app reads
-- through DATABASE_URL, not the anon key; the only anon client is src/hooks/useLiveGames.ts.
--
-- Hand-apply in the Supabase SQL editor. Not generated by drizzle-kit, not applied by any script.
--
-- 1. Before: see what anon and authenticated can do today. If this lists a table not named
--    below, decide about it before step 2.
select grantee, table_name, string_agg(privilege_type, ', ' order by privilege_type) as privileges
from information_schema.role_table_grants
where table_schema = 'public' and grantee in ('anon', 'authenticated')
group by grantee, table_name
order by table_name, grantee;

-- 2. Revoke. Supabase's default privileges can also have granted these to `authenticated`;
--    the app has no signed-in users, so it needs neither.
begin;
revoke all on table public.teams                      from anon, authenticated;
revoke all on table public.fatigue_scores             from anon, authenticated;
revoke all on table public.predictions                from anon, authenticated;
revoke all on table public.playoff_series             from anon, authenticated;
revoke all on table public.playoff_series_predictions from anon, authenticated;
revoke all on table public.shot_grid                  from anon, authenticated;
revoke all on table public.shot_value_surface         from anon, authenticated;

-- Realtime postgres_changes checks the subscriber's SELECT right, so games keeps exactly that.
revoke all on table public.games from anon, authenticated;
grant select on table public.games to anon;
commit;

-- 3. After: expect one row, anon | games | SELECT. Then open /games during a live slate and
--    confirm scores still update without a reload.
select grantee, table_name, string_agg(privilege_type, ', ' order by privilege_type) as privileges
from information_schema.role_table_grants
where table_schema = 'public' and grantee in ('anon', 'authenticated')
group by grantee, table_name
order by table_name, grantee;

-- Rollback: re-run the grant lines of 0005_supabase_grants.sql, 0006, 0007 and 0008.
